-- 프로토타입 위키(1장) → wiki_pages 일괄 이식. 한 번만 실행하세요(재실행 시 id 충돌 오류가 나면 이미 실행된 것).
insert into wiki_pages (id, user_id, section, title, definition, points, flagged)
select v.id, u.id, v.section, v.title, v.definition, v.points, v.flagged
from (values
  ('805163ab-5d52-59aa-b79c-287171bd65b3'::uuid, '1장 · 1절 · 흙의 구성과 지표', '흙의 3상 (토립자·물·공기)', '흙은 고체(토립자)·액체(물)·기체(공기)의 3상으로 구성된 다상 재료.', '["토질역학의 모든 지표(간극비·함수비·포화도 등)는 이 3상의 부피·무게 비율로 정의됨"]'::jsonb, false),
  ('1dc4c8f9-c06a-5d8f-bd0a-49e90f30ba8b'::uuid, '1장 · 1절 · 흙의 구성과 지표', '간극비 (e)', '토립자 부피에 대한 간극(물+공기) 부피의 비. e = Vv / Vs.', '["클수록 흙이 엉성함(압축성 큼). 모래보다 점토의 간극비가 일반적으로 큼"]'::jsonb, false),
  ('b58cbd40-2daf-53fa-bbb8-ace39f08a13e'::uuid, '1장 · 1절 · 흙의 구성과 지표', '간극률 (n)', '흙 전체 부피에 대한 간극 부피의 백분율. n = Vv / V × 100(%).', '["간극비는 ''토립자 대비'', 간극률은 ''전체 대비'' — e와 n은 상호 환산 가능"]'::jsonb, false),
  ('2ee85a86-ae67-5f2c-8964-e5f92a1235f1'::uuid, '1장 · 1절 · 흙의 구성과 지표', '함수비 (w)', '토립자 무게에 대한 물 무게의 백분율. w = Ww / Ws × 100(%).', '["흙의 상태(연경도)와 다짐 특성을 지배하는 가장 기본 지표"]'::jsonb, false),
  ('ae73175d-3ed7-5a55-af11-ec6080abeb82'::uuid, '1장 · 1절 · 흙의 구성과 지표', '포화도 (S)', '간극 부피 중 물이 차지하는 부피의 백분율. S = Vw / Vv × 100(%).', '["S=100%면 포화토(간극이 전부 물). 지하수위 아래 흙은 보통 포화 상태로 봄"]'::jsonb, false),
  ('bb8f74ac-9243-521f-922d-945d25728670'::uuid, '1장 · 1절 · 흙의 구성과 지표', '비중 (흙, Gs)', '토립자 무게와 같은 부피 물 무게의 비. 일반 토사는 대략 2.6~2.7 수준.', '["3상 관계식(Se = wGs)으로 다른 지표와 연결됨"]'::jsonb, false),
  ('02326b05-899b-58ed-9326-710cb4efa31a'::uuid, '1장 · 1절 · 연경도(점성토)', '아터버그한계', '점성토가 함수비에 따라 고체→반고체→소성→액성 상태로 변할 때의 경계 함수비들(수축·소성·액성한계).', '["점성토의 공학적 성질(연경도, Consistency)을 정의하는 기본 시험"]'::jsonb, false),
  ('af25b7cf-5f05-54fe-b33a-dbd981266533'::uuid, '1장 · 1절 · 연경도(점성토)', '액성한계 (LL)', '흙이 소성 상태에서 액성 상태로 넘어가는 경계 함수비. 유동곡선(낙하 횟수 25회)으로 결정.', '["클수록 물을 많이 머금는 흙(압축성 큰 점토)"]'::jsonb, false),
  ('2e512e2d-5f08-53d7-b23a-2030ca4a98a4'::uuid, '1장 · 1절 · 연경도(점성토)', '소성한계 (PL)', '흙이 반고체에서 소성 상태로 넘어가는 경계 함수비. 흙 실을 지름 3mm로 늘렸을 때 부서지기 시작하는 함수비.', '[]'::jsonb, false),
  ('f3d84674-0a36-5d62-ab1b-d2d37197a46f'::uuid, '1장 · 1절 · 연경도(점성토)', '수축한계 (SL)', '함수비를 더 줄여도 부피가 더 이상 줄지 않는 경계 함수비.', '["함수비 증가 순서: 수축한계 < 소성한계 < 액성한계 (고체→반고체→소성→액체)"]'::jsonb, false),
  ('2b54f1a5-0ca5-5bcd-a3aa-4f0f8aa31521'::uuid, '1장 · 1절 · 연경도(점성토)', '소성지수 (PI)', 'PI = LL - PL. 흙이 소성 상태로 존재할 수 있는 함수비의 폭.', '["클수록 점토분이 많고 소성이 풍부한 흙. 사질토는 비소성(NP)"]'::jsonb, false),
  ('5a2bc3b4-3802-57ec-a603-156a71d12bdd'::uuid, '1장 · 1절 · 입도와 분류', '입도분포 · 입도시험', '흙 입자의 크기별 구성 비율. 체가름시험(조립분)과 비중계시험(세립분)으로 구함.', '["균등계수(Cu)·곡률계수(Cg)로 양입도/빈입도 판정 — 양입도(입경이 고루 섞임)일수록 다짐이 잘 되는 좋은 흙"]'::jsonb, false),
  ('e3cff9f5-3028-5944-9990-804253cd37a2'::uuid, '1장 · 1절 · 입도와 분류', '통일분류법 (USCS)', '입도와 아터버그한계로 흙을 기호(G·S·M·C·O, W·P·H·L)로 분류하는 국제적 분류법.', '["예: GW(입도 좋은 자갈), SP(입도 나쁜 모래), CL(저소성 점토), CH(고소성 점토)"]'::jsonb, false),
  ('d4e5ab4b-edb4-5474-a633-1d26067b605b'::uuid, '1장 · 1절 · 입도와 분류', '점토 · 실트 · 모래 · 자갈', '입경 크기 순: 점토 < 실트 < 모래 < 자갈. 경계 입경 수치는 분류법마다 다름.', '["점토=점착력 있음·투수 낮음·압밀침하 / 모래=점착력 없음·투수 큼·즉시침하·액상화 — 이 대비가 토질 전체를 관통함"]'::jsonb, true),
  ('88313ce6-0dc5-5140-81df-24212fd93270'::uuid, '1장 · 1절 · 강도와 상태지표', 'N치 (표준관입시험 타격횟수)', '샘플러를 30cm 관입시키는 데 필요한 해머(63.5kg, 낙하고 76cm) 타격 횟수. 지반의 조밀함·굳기 지표.', '["N치가 클수록 조밀·견고. 사질토는 상대밀도, 점성토는 연경도(컨시스턴시) 추정에 사용"]'::jsonb, true),
  ('a425d538-f22d-5a69-8762-e4bb6c1e014a'::uuid, '1장 · 1절 · 강도와 상태지표', '상대밀도 (Dr)', '사질토가 가장 엉성한 상태와 가장 조밀한 상태 사이 어디에 있는지 나타내는 백분율.', '["사질토 전용 지표. 액상화 가능성 평가와 직결(느슨한 모래일수록 위험)"]'::jsonb, false),
  ('392a846e-cb25-59fd-b2bf-99416a9708c4'::uuid, '1장 · 1절 · 강도와 상태지표', '점착력 (c)', '입자 간 인력으로 전단에 저항하는 성분. 점성토의 강도 원천.', '["사질토는 점착력 0, 순수 점토는 마찰각 0으로 단순화하여 해석하는 경우가 많음"]'::jsonb, false),
  ('23a30f27-6a59-5653-95c0-7e9cfa5e430b'::uuid, '1장 · 1절 · 강도와 상태지표', '내부마찰각 (파이)', '입자 간 마찰·맞물림으로 전단에 저항하는 성분의 각도. 사질토의 강도 원천.', '[]'::jsonb, false),
  ('ec81ba86-798c-5432-8876-63df635116d0'::uuid, '1장 · 1절 · 강도와 상태지표', '전단강도 (흙)', '흙이 미끄러짐(전단파괴)에 저항하는 최대 응력. 쿨롱(Coulomb) 식: 점착력 + 유효응력×tan(내부마찰각).', '["사면 붕괴·지지력·토압 등 토질 문제의 대부분은 전단강도 문제로 귀결", "''점토는 점착력으로 버티고, 모래는 마찰각으로 버틴다''"]'::jsonb, false),
  ('034ca73a-3a29-5d06-9f44-69a862272c1e'::uuid, '1장 · 1절 · 강도와 상태지표', '예민비 (Sensitivity)', '불교란 시료 강도 ÷ 교란(이긴) 시료 강도. 흐트러졌을 때 강도가 얼마나 떨어지는지의 비.', '["예민비가 큰 점토(예민 점토)는 시공 중 교란되면 강도가 급감 — 말뚝 항타·굴착 시 주의"]'::jsonb, false),
  ('cc75d915-3a32-5f46-b53a-37a72d92be13'::uuid, '1장 · 1절 · 강도와 상태지표', '틱소트로피 (Thixotropy)', '교란으로 강도가 떨어진 점토가 시간이 지나며 강도를 회복하는 현상.', '["예민비(흐트러지면 약해짐)와 틱소트로피(가만두면 회복)는 짝으로 출제되는 단골 개념"]'::jsonb, false),
  ('0bbc52dd-4f79-5238-beff-f7009d3fe22b'::uuid, '1장 · 1절 · 압밀·투수·기타현상', '압밀 (Consolidation)', '포화 점성토가 하중을 받아 간극수가 서서히 빠져나가며 부피가 줄어드는 현상.', '["물이 빠지는 속도가 느려 침하가 장기간 지속 — 점성토 침하의 본질"]'::jsonb, false),
  ('7b9bb44e-0a22-5046-a14a-30103ace7f39'::uuid, '1장 · 1절 · 압밀·투수·기타현상', '압밀침하', '압밀에 의해 발생하는 장기 침하.', '["테르자기 압밀이론으로 침하량·침하시간 산정. 연약지반 위 구조물 장기 침하의 주원인 — 선행재하 등 지반개량으로 대응"]'::jsonb, false),
  ('0fa46640-621b-5496-b6ff-d6968ee79c5d'::uuid, '1장 · 1절 · 압밀·투수·기타현상', '즉시침하 (탄성침하)', '하중 재하 직후 곧바로 발생하는 침하. 사질토와 불포화토에서 지배적.', '["모래=즉시침하(빠르고 끝), 점토=압밀침하(느리고 오래) — 침하의 시간 특성 대비"]'::jsonb, false),
  ('5225a020-5d11-5005-9621-317c1d3036c1'::uuid, '1장 · 1절 · 압밀·투수·기타현상', '투수계수 (k)', '물이 흙 속을 통과하는 속도의 지표(다르시 법칙 v = ki).', '["자갈·모래는 크고 점토는 매우 작음. 배수공법 선정·보일링 검토의 기초"]'::jsonb, false),
  ('c6f03620-b71e-59a8-b77b-a60bfb1e4dc4'::uuid, '1장 · 1절 · 압밀·투수·기타현상', '모관현상', '간극이 가는 흙에서 물이 표면장력으로 지하수위 위로 상승하는 현상.', '["세립토일수록 상승고가 큼"]'::jsonb, false),
  ('43238891-e6f2-5baf-b94e-2436657dd37d'::uuid, '1장 · 1절 · 압밀·투수·기타현상', '동상 · 융해', '동상은 흙 속 수분이 얼며 아이스렌즈가 성장해 지반이 솟는 현상, 융해는 봄에 녹으며 지지력이 급감하는 현상.', '["조건 3요소: 동결 온도·물 공급·동상 취약토(실트질). 대책: 치환·차수·단열", "동결심도 아래에 기초 저면을 두는 것이 기초 설계의 기본"]'::jsonb, false),
  ('5b6e4bc4-933c-577a-a0cb-ae0243662154'::uuid, '1장 · 1절 · 압밀·투수·기타현상', '액상화 (Liquefaction)', '포화된 느슨한 모래지반이 지진 등 진동으로 간극수압이 급상승, 유효응력을 잃고 액체처럼 거동하는 현상.', '["조건: 느슨한 세립 모래 + 포화(지하수위 얕음) + 반복 진동", "대책: 다짐(SCP·바이브로플로테이션), 배수(그래블드레인), 지하수위 저하"]'::jsonb, false),
  ('c8e16f28-0d39-51c5-bdb7-3d6af3767fc9'::uuid, '1장 · 2절 · 예비조사', '지하탐사 (짚어보기 · 터파보기)', '짚어보기는 철봉을 꽂아 저항으로 얕은 지반을 가늠, 터파보기(시험굴, Test Pit)는 직접 파서 눈으로 지층·지하수 확인.', '["소규모·예비 조사 수단. 본조사는 보링·사운딩으로"]'::jsonb, false),
  ('67cea7fe-39c2-58ee-bbfb-940a4aab4f43'::uuid, '1장 · 2절 · 예비조사', '물리탐사 (탄성파 · 전기비저항)', '지반에 탄성파나 전류를 보내 전파 속도·저항 분포로 지층 구조를 넓게 추정하는 간접 조사.', '["넓은 범위를 빠르게 — 다만 정밀도는 보링보다 낮아 보완용"]'::jsonb, false),
  ('346c7f33-97b9-5a95-8955-5843dfe7e761'::uuid, '1장 · 2절 · 보링', '보링 (Boring)', '지반에 구멍을 뚫어 시료 채취·지층 확인·원위치시험을 수행하는 대표적 본조사.', '["부지 규모에 따라 간격·심도 계획(지지층 확인 심도까지)"]'::jsonb, false),
  ('70206140-3f71-5997-adf5-856583d45429'::uuid, '1장 · 2절 · 보링', '오거보링', '나선형 오거를 회전시켜 굴진. 얕은 심도·점성토에 적합, 간편하지만 시료 교란 큼.', '[]'::jsonb, false),
  ('eda4046d-ded9-558e-9d44-4ee2bdf86b9d'::uuid, '1장 · 2절 · 보링', '수세식보링', '물을 분사해 흙을 씻어 올리며 굴진. 연약토에 빠르지만 세립분 유실로 시료 품질 낮음.', '[]'::jsonb, false),
  ('6ccf172c-e2a7-509c-97ac-3751b8882dd7'::uuid, '1장 · 2절 · 보링', '회전식보링', '비트를 회전시키며 굴진하고 코어를 채취. 정밀도가 가장 높아 암반 조사 표준.', '["정밀도: 회전식 > 충격식·수세식·오거 — ''돌려 파는 게 제일 정확''"]'::jsonb, false),
  ('91278e86-9844-5e50-a591-becd793bddc4'::uuid, '1장 · 2절 · 보링', '충격식보링', '비트를 낙하 충격으로 파쇄하며 굴진. 자갈·전석층 등 단단한 층 통과에 사용, 시료 교란 큼.', '[]'::jsonb, false),
  ('77a45586-69ed-595a-a496-c0d38b1f3a5f'::uuid, '1장 · 2절 · 보링', '토질주상도', '보링 결과를 깊이별로 지층·N치·지하수위·시료 위치와 함께 기둥 그림으로 정리한 도면.', '["기초·흙막이 설계의 출발점이 되는 핵심 성과물"]'::jsonb, false),
  ('646ce54e-7107-58f4-9f57-2bddfb35459a'::uuid, '1장 · 2절 · 샘플링', '샘플링 (시료 채취)', '지반의 흙을 시험용으로 채취하는 일. 교란 정도에 따라 시험 용도가 갈림.', '[]'::jsonb, false),
  ('cdc8dcd5-e4b3-59ab-9d8c-f3283602dc0e'::uuid, '1장 · 2절 · 샘플링', '교란시료', '구조가 흐트러진 시료 — 입도·함수비 등 물성시험용.', '["''물성은 교란으로도 OK, 역학은 불교란이어야'' — 시험 목적으로 구분"]'::jsonb, false),
  ('49a31b30-b5fd-57f6-b0cf-a263093e33bc'::uuid, '1장 · 2절 · 샘플링', '불교란시료', '원위치 구조를 보존한 시료(신월튜브 등) — 전단강도·압밀 등 역학시험용.', '[]'::jsonb, false),
  ('4461fae8-f0a8-5e69-b44a-b41f0ebd3c0e'::uuid, '1장 · 2절 · 사운딩·원위치시험', '사운딩 (Sounding)', '로드 끝의 저항체를 지중에 관입·회전·인발하며 저항으로 지반 성상을 조사하는 원위치시험의 총칭.', '["대표: 표준관입시험(동적), 콘관입·베인시험(정적)"]'::jsonb, false),
  ('add042d0-626e-56ef-b54f-3a22d8ff244d'::uuid, '1장 · 2절 · 사운딩·원위치시험', '표준관입시험 (SPT)', '보링공에서 스플릿스푼 샘플러를 표준 해머로 타격해 N치를 구하는 시험. 교란시료도 동시에 채취.', '["사질토에 특히 유효(점성토는 참고치). 전 세계적으로 가장 보편적인 지반조사"]'::jsonb, false),
  ('7f92b2d3-b98f-5f04-b385-6ca426a568a3'::uuid, '1장 · 2절 · 사운딩·원위치시험', '베인시험 (Vane Test)', '십자 날개(베인)를 연약 점토에 꽂고 회전시켜 비배수 전단강도(점착력)를 구하는 시험.', '["연약 점성토 전용 — N치가 무의미한 초연약 지반에서 사용"]'::jsonb, false),
  ('bfa3c9bf-1301-578c-a387-b2a28781f36f'::uuid, '1장 · 2절 · 사운딩·원위치시험', '콘관입시험 (CPT)', '원추(콘)를 일정 속도로 정적 압입하며 선단저항·주면마찰을 연속 측정하는 시험.', '["SPT는 ''때려서(동적) 30cm'', CPT는 ''눌러서(정적) 연속 측정'' — 관입 방식으로 구분"]'::jsonb, false),
  ('160787a9-2caf-5008-98df-5e50d7ffc2e3'::uuid, '1장 · 2절 · 사운딩·원위치시험', '평판재하시험 (PBT)', '재하판에 하중을 단계적으로 가해 하중-침하 곡선으로 지반 지지력(지지력계수)을 직접 구하는 시험.', '["재하판 크기와 실제 기초 크기 차이(크기 효과)에 주의 — 깊은 지층 상태는 반영 못 함"]'::jsonb, false),
  ('edd5f7d4-9a89-5198-ab87-b64fca26ad31'::uuid, '1장 · 2절 · 사운딩·원위치시험', '지내력시험', '기초 지반이 설계 지내력을 갖는지 확인하는 시험의 총칭(실무상 평판재하시험으로 수행).', '[]'::jsonb, false),
  ('b388a27c-0131-5b8f-8f54-78f1c556f82c'::uuid, '1장 · 2절 · 사운딩·원위치시험', '지하수위 조사', '보링공 내 수위 관측 등으로 지하수위와 그 변동을 파악하는 조사.', '["흙막이 차수·배수 계획, 부력 검토, 보일링·액상화 평가의 필수 정보"]'::jsonb, false),
  ('9db0787a-44b7-5fc7-abcf-72e97d9eafa7'::uuid, '1장 · 3절 · 굴착과 흙운반', '절토 (흙깎기)', '원지반을 계획고까지 깎아내는 작업.', '["깎은 비탈면의 안정(사면 붕괴)이 안전 포인트 — 구배 기준 준수"]'::jsonb, true),
  ('5acc94ec-e31d-5ad1-b09c-1515d6fef4a0'::uuid, '1장 · 3절 · 굴착과 흙운반', '성토 (흙쌓기)', '흙을 쌓아 계획고를 만드는 작업. 층별로 얇게 깔고 다짐하며 올라가는 것이 원칙(층다짐).', '["절토(깎기)↔성토(쌓기), 그리고 ''성토는 반드시 다짐과 세트''"]'::jsonb, false),
  ('114704df-85e6-5315-84b8-b121850a03b3'::uuid, '1장 · 3절 · 굴착과 흙운반', '터파기', '기초·지하 구조물 시공을 위해 지반을 파는 작업(온통파기·줄파기·구덩이파기).', '[]'::jsonb, false),
  ('ad199ff1-7d31-50c6-af18-2165a69742c1'::uuid, '1장 · 3절 · 굴착과 흙운반', '되메우기', '구조물 완성 후 터파기 공간을 흙으로 되채우는 작업. 층별 다짐, 양질토 사용이 원칙.', '["다짐 불량 시 지표 침하·배관 파손 — 준공 후 하자의 단골 원인"]'::jsonb, false),
  ('f72ed34e-7c6b-58e7-be27-1c99a9660998'::uuid, '1장 · 3절 · 굴착과 흙운반', '잔토처리', '터파기량 중 되메우기 후 남는 흙을 장외 반출·처리하는 일. 사토장 선정과 운반 계획 포함.', '[]'::jsonb, false),
  ('74f65a43-a1b6-57fc-9ade-c824a4548242'::uuid, '1장 · 3절 · 굴착과 흙운반', '토량환산계수 (L값 · C값)', '자연상태 흙 1에 대한 부피 변화율. L = 흐트러진 상태/자연상태(>1, 운반량 산정), C = 다져진 상태/자연상태(<1, 다짐량 산정).', '["''L은 Loose(부풀음), C는 Compact(압축)'' — 운반은 L로, 성토는 C로 계산"]'::jsonb, false),
  ('108a5a56-6b51-51cd-ac62-8b15f4c568e6'::uuid, '1장 · 3절 · 다짐', '다짐 (Compaction)', '기계 에너지로 흙 속 공기를 빼내 밀도를 높이는 작업.', '["다짐은 ''공기 제거(즉시)'', 압밀은 ''물 제거(장기)'' — 시험 단골 비교"]'::jsonb, false),
  ('6f4e9cb8-bdf4-58a8-94b0-850ed9fe9e36'::uuid, '1장 · 3절 · 다짐', '다짐도', '현장 건조밀도 ÷ 실내 최대건조밀도 × 100(%). 다짐 품질의 판정 기준(예: 95% 이상).', '["현장 밀도는 모래치환법(들밀도시험) 등으로 측정"]'::jsonb, true),
  ('d5e6fedc-5300-54b2-adcd-cdf6b60572ca'::uuid, '1장 · 3절 · 다짐', '최적함수비 (OMC)', '일정 다짐에너지에서 건조밀도가 최대가 되는 함수비. 다짐곡선의 정점.', '["너무 말라도, 너무 젖어도 다짐 효율이 떨어짐 — OMC 부근에서 다짐하는 것이 원칙"]'::jsonb, false),
  ('a609ba7a-9da9-5ecf-9d1a-6ca5a9dbd543'::uuid, '1장 · 3절 · 다짐', '롤러 · 래머 · 탬퍼', '다짐 장비 — 롤러(넓은 면적 전압: 진동롤러·타이어롤러), 래머(충격 다짐, 소형), 탬퍼(협소부 다짐).', '["사질토는 진동 다짐, 점성토는 전압(누름) 다짐이 효과적"]'::jsonb, false),
  ('835af611-1d70-5677-b0da-4a80ccc6ec0f'::uuid, '1장 · 3절 · 비탈면과 굴착방식', '법면 (비탈면) · 소단', '법면은 절·성토로 생긴 경사면, 소단은 높은 비탈 중간에 두는 수평 단(빗물 처리·안정·점검용).', '[]'::jsonb, false),
  ('a3181ccb-8fd3-5aea-9c27-f60c8cba54b5'::uuid, '1장 · 3절 · 비탈면과 굴착방식', '오픈컷 (Open Cut)', '부지에 여유가 있을 때 비탈면을 두고 개방 굴착하는 방식(비탈면 오픈컷) 또는 흙막이를 세우고 전면 개방 굴착하는 방식(흙막이 오픈컷).', '["가장 단순·경제적이나 부지 여유와 인접 조건이 관건"]'::jsonb, false),
  ('adbc4024-186a-5771-9b96-3ab39540172f'::uuid, '1장 · 3절 · 비탈면과 굴착방식', '아일랜드컷 공법', '중앙부를 먼저 굴착·구축하고, 그 구조물에 버팀대를 걸어 주변부를 나중에 굴착하는 공법.', '["얕고 넓은 굴착에 유리"]'::jsonb, false),
  ('d610d3d0-2d02-5e82-a4a2-8437cb9ba5b9'::uuid, '1장 · 3절 · 비탈면과 굴착방식', '트렌치컷 공법', '아일랜드컷의 역순 — 주변부를 도랑(trench)처럼 먼저 굴착·구축 후 중앙부를 굴착.', '["''아일랜드 = 섬(중앙) 먼저, 트렌치 = 도랑(둘레) 먼저'' — 지반이 연약해 전면 굴착이 어려울 때, 깊고 넓은 굴착에 적용"]'::jsonb, false),
  ('e7fb95c1-ca79-5dc0-b5af-e449df9bdb4b'::uuid, '1장 · 3절 · 비탈면과 굴착방식', '언더피닝 (Underpinning)', '기존 구조물 기초를 보강·신설하여 지지하는 공법(인접 굴착 시 기존 건물 보호, 기초 침하 보수 등).', '["인접 근접시공 분쟁·침하 사고와 직결되는 중요 공법"]'::jsonb, false),
  ('c23e5f0c-0d39-524f-9856-3f4edf1e929d'::uuid, '1장 · 3절 · 비탈면과 굴착방식', '암반 발파 · 브레이커', '암 굴착 방법 — 화약 발파(대량·경제적, 진동·소음 민원)와 유압 브레이커(무진동 요구 시, 능률 낮음). 미진동·무진동 공법(할암 등)도 사용.', '["시험발파로 진동 허용치 검토 후 본발파 — 도심 발파 관리 포인트"]'::jsonb, true),
  ('ecff361d-20e2-5dc5-93be-d554d52eddb4'::uuid, '1장 · 4절 · 흙막이 벽체', '흙막이', '굴착 시 주변 지반의 붕괴·침하·지하수 유입을 막는 가설 벽체와 지보의 총칭.', '["구성 = 벽체(토압을 받는 벽) + 지보공(벽을 받치는 버팀 시스템) + 차수·배수 대책"]'::jsonb, false),
  ('0c5a6f01-afa9-5c76-902d-7772591d04ff'::uuid, '1장 · 4절 · 흙막이 벽체', '엄지말뚝 + 토류판 공법 (H-pile)', 'H형강 말뚝을 일정 간격으로 박고 굴착하며 사이에 토류판(나무판)을 끼워 흙을 막는 공법.', '["가장 경제적·보편적. 단, 차수성이 없어 지하수 많은 곳은 부적합"]'::jsonb, false),
  ('119172bc-1ae1-5009-b00a-db92d0dab5b6'::uuid, '1장 · 4절 · 흙막이 벽체', '시트파일 (강널말뚝)', '요철 이음이 있는 강판 말뚝을 연속으로 박아 벽체를 만드는 공법.', '["차수성 있음 — 연약지반에 유리. 타입 시 소음·진동, 자갈층 관입 곤란"]'::jsonb, false),
  ('3a6c17e2-fd75-59ab-8de9-eb8f99202c98'::uuid, '1장 · 4절 · 흙막이 벽체', 'CIP (Cast In Placed pile)', '오거로 천공 후 철근망·H형강을 넣고 콘크리트(모르타르)를 타설해 주열식(기둥 나열) 벽체를 만드는 공법.', '["강성이 크고 소음·진동 적음. 기둥 사이 이음부 차수는 별도 그라우팅 보강 필요"]'::jsonb, false),
  ('82ef5ef3-619f-5f47-b754-05b017025e3f'::uuid, '1장 · 4절 · 흙막이 벽체', 'SCW (Soil Cement Wall)', '오거로 원지반 흙과 시멘트밀크를 교반·혼합해 소일시멘트 벽체를 만들고 H형강을 삽입하는 공법.', '["차수성 양호, 저소음·저진동. 강도는 CIP보다 낮음", "주열식 3형제: CIP(콘크리트 기둥) / SCW(흙+시멘트 교반) — ''갈아 넣나, 새로 치나''로 구분"]'::jsonb, false),
  ('6e2fcf90-04b2-567b-a2c8-02502b04e3ad'::uuid, '1장 · 4절 · 흙막이 벽체', '슬러리월 (지하연속벽, Slurry Wall)', '안정액으로 공벽을 보호하며 패널 단위로 굴착 → 철근망 삽입 → 콘크리트 타설로 연속 철근콘크리트 벽체를 만드는 공법.', '["강성·차수성 최고, 본구조체 겸용 가능, 대심도·도심 대형 현장의 표준. 비용·장비 규모가 큼"]'::jsonb, false),
  ('887ee11d-4547-5623-adc2-fbaefd90d7e8'::uuid, '1장 · 4절 · 흙막이 벽체', '가이드월 (Guide Wall)', '슬러리월 굴착 전 지표부에 설치하는 안내벽. 굴착 위치 유도, 지표부 붕괴 방지, 철근망 거치대 역할.', '[]'::jsonb, false),
  ('a0dfb84a-96e5-504d-b98d-dfb03cd30c8d'::uuid, '1장 · 4절 · 흙막이 벽체', '안정액 (벤토나이트)', '굴착공 벽면에 불투수막(머드케이크)을 만들어 공벽 붕괴를 막는 현탁액.', '["비중·점성·사분율 등 품질관리 항목. 슬러리월·현장타설말뚝 공통 사용"]'::jsonb, false),
  ('bb1b47ef-20c6-5f28-aead-e16cf43c555b'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '버팀대 (Strut)', '흙막이 벽 사이를 수평으로 가로질러 토압을 반대편 벽으로 전달하는 압축 부재.', '["굴착 폭이 넓으면 중간말뚝·좌굴 보강 필요. 버팀대가 많으면 굴착·구조물 시공에 지장"]'::jsonb, false),
  ('8e9c61a6-43fb-578c-a67a-90d9beb5aabc'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '띠장 (Wale)', '흙막이 벽을 따라 수평으로 대어 벽의 토압을 모아 버팀대·앵커에 전달하는 부재.', '["힘의 흐름: 벽체 → 띠장 → 버팀대(또는 앵커) → 반대벽(또는 지반). 이 흐름 하나로 지보 구조가 정리됨"]'::jsonb, false),
  ('846e8d79-acac-5537-b051-ef81f211d62f'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '코너스트럿', '모서리를 비스듬히 지르는 짧은 버팀대.', '[]'::jsonb, false),
  ('faccd21c-a807-5478-88bb-45a33182ae4d'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '화타 (까치발·사보강재)', '띠장과 버팀대 사이 경사 보강재로 버팀 간격을 넓히는 부재.', '[]'::jsonb, false),
  ('b068670e-c39a-5d8c-83e8-b6b2fdf7a1c8'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '어스앵커 (Earth Anchor)', '흙막이 벽 배면 지반에 천공 후 PS강선을 넣고 그라우팅해 정착시켜, 인장력으로 벽을 당겨 지지하는 공법.', '["굴착 내부가 비어 시공성 우수. 배면에 부지(인접 대지 침범 동의)가 필요, 정착부 지반이 양호해야 함", "''버팀대(안에서 밀어 지지·압축) ↔ 어스앵커(밖에서 당겨 지지·인장)'' — 힘의 방향이 반대"]'::jsonb, false),
  ('49f0dccb-b5c7-5d54-822c-b4685b4084d3'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '제거식 앵커', '굴착 완료 후 강선을 회수할 수 있는 앵커. 인접 대지에 강선이 남는 문제(민원·향후 공사 지장)를 해소.', '[]'::jsonb, false),
  ('0ecf35a3-8746-592c-8367-5900ca88e37c'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '소일네일링 (Soil Nailing)', '굴착면에 짧은 보강재(네일)를 촘촘히 박고 숏크리트로 표면을 보호해 지반 자체를 보강해 흙벽으로 만드는 공법.', '["별도 벽체 없이 원지반을 활용 — 얕은 굴착·사면 보강에 적합. 지하수 많은 곳 부적합"]'::jsonb, false),
  ('505e61f1-f210-520c-9ccf-c603ea002fd8'::uuid, '1장 · 4절 · 지보공(버팀시스템)', '레이커 (Raker)', '굴착 바닥에서 흙막이 벽을 향해 비스듬히 받치는 경사 버팀대.', '["버팀대를 걸 반대벽이 없거나 굴착 폭이 넓을 때 사용. 바닥 지지블록(킥커) 필요"]'::jsonb, false),
  ('388a2c3b-2193-5881-8ed4-87d043be9f57'::uuid, '1장 · 4절 · 지보공(버팀시스템)', 'IPS 공법', '띠장에 프리스트레스를 도입해 버팀대 개수를 줄이는 지보 공법(Innovative Prestressed Support).', '["버팀대가 줄어 굴착·작업 공간이 넓어짐"]'::jsonb, false),
  ('481a85fb-575a-5742-bb46-5b2d5caedfb2'::uuid, '1장 · 4절 · 지보공(버팀시스템)', 'SPS 공법', '가설 버팀대 대신 본구조물의 철골 기둥·보를 지보공으로 활용하는 공법(Strut as Permanent System).', '["가설재 철거 + 역타와 결합해 공기 단축, 해체 공정이 없어짐"]'::jsonb, false),
  ('382cdfc2-7e1e-5c5e-917a-83e9524c5599'::uuid, '1장 · 4절 · 굴착순서공법', '역타공법 (탑다운, Top-Down)', '슬러리월과 기둥(RC 또는 철골)을 먼저 시공하고, 1층 슬래브부터 아래로 굴착과 지하 골조를 반복하며 내려가는 공법. 지상 골조 동시 진행 가능.', '["장점: 1층 슬래브가 버팀대 역할(안정성), 공기 단축, 소음·분진 차단, 인접 영향 최소", "단점: 지하 작업환경(조명·환기) 열악, 굴착 장비 제한, 이음부 품질관리 난이도, 비용"]'::jsonb, false),
  ('aec1e4c9-4eca-51ff-8902-b971526d5ab6'::uuid, '1장 · 4절 · 굴착순서공법', '순타공법 (바텀업, Bottom-Up)', '흙막이+지보로 최하부까지 굴착을 끝낸 뒤 기초부터 위로 골조를 올리는 일반적 공법.', '["''순타(다 파고 아래→위) ↔ 역타(파면서 위→아래) — 도심 대심도·인접 민감 현장일수록 역타 유리''"]'::jsonb, false),
  ('75b78ba8-8525-5c82-903e-5a21610b5485'::uuid, '1장 · 4절 · 토압·기초', '근입장', '흙막이 벽이 굴착 바닥면 아래로 박혀 들어간 깊이.', '["근입장이 부족하면 히빙·보일링·벽체 회전(킥아웃) 발생 — 안정 검토의 핵심 변수"]'::jsonb, false),
  ('3177113c-cab2-5e1d-badf-31bad942b0e1'::uuid, '1장 · 4절 · 토압·기초', '주동토압', '벽이 흙에서 멀어질 때(흙이 벽을 미는) 최소 토압.', '["흙막이 벽 배면은 주동토압으로 밀리고, 근입부 앞쪽은 수동토압으로 버틴다 — 벽 안정의 기본 그림"]'::jsonb, false),
  ('c4770253-a5d3-5ec7-84d1-26a45cf67ffb'::uuid, '1장 · 4절 · 토압·기초', '수동토압', '벽이 흙을 밀 때(흙이 저항하는) 최대 토압.', '["크기: 주동 < 정지 < 수동"]'::jsonb, false),
  ('15b897b8-09d4-5c2a-b758-7ad9f5ff5f0c'::uuid, '1장 · 4절 · 토압·기초', '정지토압', '벽 변위가 없을 때의 토압.', '[]'::jsonb, false),
  ('f2f00a75-3613-5f9a-b56e-e65bf14b9f1d'::uuid, '1장 · 5절 · 계측관리', '계측관리', '굴착 중 지반·벽체·인접 구조물의 거동을 계기로 측정해 설계 예측과 비교, 위험을 조기 감지하는 관리.', '["정보화 시공의 핵심 — 관리기준치(주의·경고·위험) 설정 후 초과 시 대응 절차 가동"]'::jsonb, false),
  ('09c3c658-8b9a-5840-a2ec-75146f32a28a'::uuid, '1장 · 5절 · 계측관리', '지중경사계 (Inclinometer)', '지중에 매설한 관의 기울기 변화로 흙막이 벽·지반의 수평 변위(깊이별)를 측정하는 계기.', '["흙막이 붕괴 전조(벽체 배부름)를 가장 직접적으로 보여주는 대표 계측기"]'::jsonb, false),
  ('844a7377-bf97-5787-aba6-30202b0e4688'::uuid, '1장 · 5절 · 계측관리', '지하수위계', '굴착에 따른 지하수위 변동을 측정. 급격한 저하는 주변 침하, 급상승은 벽체 수압 증가 신호.', '[]'::jsonb, false),
  ('0af0941e-77e9-5f1d-b810-15519ab74bcf'::uuid, '1장 · 5절 · 계측관리', '변형률계 (Strain Gauge)', '버팀대·띠장 등 부재 표면에 부착해 변형률(≒응력)을 측정. 부재가 설계 하중을 초과하는지 감시.', '["변형률계는 ''부재가 얼마나 늘었나'', 하중계는 ''힘이 얼마나 걸렸나'' — 앵커 두부엔 하중계가 표준"]'::jsonb, false),
  ('4ac690b4-8273-57b6-a852-0e537e9a3617'::uuid, '1장 · 5절 · 계측관리', '하중계 (Load Cell)', '버팀대·어스앵커에 걸리는 축력(하중)을 직접 측정하는 계기.', '[]'::jsonb, false),
  ('bf4c8bce-a720-549d-b1f8-b8f6786ca513'::uuid, '1장 · 5절 · 계측관리', '침하계 (지표침하계 · 층별침하계)', '지표 또는 지중 깊이별 침하량을 측정. 인접 건물·도로의 침하 감시에 필수.', '[]'::jsonb, false),
  ('e0705e83-d2b2-58da-ad87-5354c63c45b2'::uuid, '1장 · 5절 · 계측관리', '균열계 (Crack Gauge)', '인접 구조물 기존 균열에 설치해 균열 폭의 진행 여부를 측정.', '["민원·분쟁 대비 증거자료로도 중요"]'::jsonb, false),
  ('edbc75d7-ce49-5de6-902a-bcd698702334'::uuid, '1장 · 5절 · 계측관리', '소음 · 진동계', '발파·항타·장비 작업의 소음과 진동을 측정해 법적 허용치 이내로 관리.', '[]'::jsonb, true),
  ('da729de6-c9ca-5842-b6e0-f33106a5d2f4'::uuid, '1장 · 5절 · 지하수 대책', '배수공법', '지하수위를 낮춰 굴착을 돕는 공법의 총칭(중력배수: 집수정·딥웰 / 강제배수: 웰포인트 등).', '["수위 저하는 주변 지반 압밀침하를 유발할 수 있음 — 인접 영향 검토 필수"]'::jsonb, false),
  ('b79d34d7-092a-545a-9ff3-264715000d3d'::uuid, '1장 · 5절 · 지하수 대책', '집수정 공법', '굴착 바닥 한쪽에 깊은 웅덩이(집수정)를 파서 물을 모아 펌프로 배수하는 가장 단순한 중력배수.', '[]'::jsonb, false),
  ('5ca7f9f6-5fd5-5444-8b73-4fb0f0152d76'::uuid, '1장 · 5절 · 지하수 대책', '웰포인트 공법 (Well Point)', '소구경 흡입관(웰포인트)을 촘촘히 박고 진공펌프로 지하수를 강제 흡입 배수하는 공법.', '["사질토·실트질 지반의 수위 저하에 유효. 흡입 한계로 1단당 저하 깊이 제한(약 5~6m)"]'::jsonb, true),
  ('cd3148b1-9260-5485-bfd4-5a6a1c757c8f'::uuid, '1장 · 5절 · 지하수 대책', '딥웰 공법 (Deep Well)', '대구경 우물을 깊게 파고 수중펌프로 대량 배수하는 중력배수 공법. 투수성 큰 지반·대심도에 적합.', '["웰포인트(진공 강제·촘촘·얕게) ↔ 딥웰(중력·큰 우물·깊게)"]'::jsonb, false),
  ('d6be7d14-c975-5ed4-8800-bd7b520a7f83'::uuid, '1장 · 5절 · 지하수 대책', '차수공법', '물의 유입 자체를 막는 공법(시트파일·슬러리월 등 차수벽, 약액주입·고압분사 그라우팅).', '["배수(물을 빼낸다) ↔ 차수(물을 막는다) — 인접 침하가 우려되면 배수보다 차수 우선"]'::jsonb, false),
  ('3cb96ccb-d8fc-5122-9437-c5777b794a7f'::uuid, '1장 · 5절 · 지하수 대책', '복수공법 (리차지, Recharge)', '배수로 낮아진 주변 지하수위를 회복시키기 위해 물을 지반에 되돌려 넣는 공법.', '["인접 지반 침하·우물 고갈 민원 대책"]'::jsonb, false),
  ('2f43e70b-ab2a-5bdc-bbb5-b49757f7abab'::uuid, '1장 · 5절 · 지반사고', '히빙 (Heaving)', '연약 점성토 굴착에서 배면 흙의 중량이 굴착 바닥 지반의 지지력을 눌러 이겨, 바닥이 부풀어 오르며 배면이 침하하는 파괴.', '["대책: 근입장 깊게(양질층까지), 배면 하중 경감, 지반개량, 부분 굴착"]'::jsonb, false),
  ('c0a59c74-d1f5-5649-895f-d434c345fe6b'::uuid, '1장 · 5절 · 지반사고', '보일링 (Boiling)', '사질토 굴착에서 벽체 안팎 수위차로 상향 침투수압이 커져, 바닥 모래가 끓듯 솟아오르며 지지력을 잃는 파괴.', '["대책: 근입장 연장(침투 경로 길게), 지하수위 저하(배수), 차수벽", "히빙=점토·흙의 무게 문제 / 보일링=모래·물의 압력 문제 — ''점토는 무게로, 모래는 물로 무너진다''"]'::jsonb, false),
  ('f54f1879-c574-533d-b7a9-5912dbad294e'::uuid, '1장 · 5절 · 지반사고', '파이핑 (Piping)', '보일링이 국부에서 진행되어 물길(파이프)이 형성, 토사가 계속 유출되며 배면 지반이 함몰되는 현상.', '["흙막이 배면 공동·도로 함몰 사고의 전형적 메커니즘"]'::jsonb, false),
  ('0beae12d-322f-5463-9e21-003a6f21fafa'::uuid, '1장 · 5절 · 지반사고', '부등침하 (Differential Settlement)', '구조물 기초가 위치별로 다르게 침하하는 현상. 건물 균열·기울음의 원인.', '["원인: 연약층 두께 상이, 이질 지반, 지하수위 저하, 인접 굴착, 증축 편심 등", "대책: 기초 통일(온통·매트), 지반개량, 건물 경량화·강성 확보, 신축줄눈 분리"]'::jsonb, false),
  ('bbbb0066-96fb-5199-8890-c7753eee1499'::uuid, '1장 · 5절 · 지반사고', '싱크홀 (지반함몰)', '지중 공동이 커지다 지표가 갑자기 꺼지는 현상.', '["상하수도 누수로 인한 토사 유출, 굴착 배면 유출 등이 주원인"]'::jsonb, false),
  ('e214c193-b81c-5579-997e-9fed0b78e077'::uuid, '1장 · 5절 · 지반사고', '인접건물 침하 · 균열 관리', '굴착 전 사전조사(균열·기울기 현황 기록, 사진·공증), 계측기 설치, 관리기준 운영으로 분쟁·피해를 예방하는 활동.', '["사전 현황조사가 없으면 ''원래 있던 균열''을 두고 분쟁 — 실무 필수 절차"]'::jsonb, false),
  ('8084afd4-b691-5fd4-976d-faf8ec728766'::uuid, '1장 · 6절 · 치환·재하', '치환공법', '연약토를 파내고 양질토(모래·쇄석)로 바꿔 넣는 가장 확실한 개량. 얕은 연약층에 경제적.', '[]'::jsonb, false),
  ('85ecc02e-e4ea-5791-8cae-cf15322398f2'::uuid, '1장 · 6절 · 치환·재하', '선행재하공법 (프리로딩, Preloading)', '구조물 시공 전 성토 등으로 미리 하중을 가해 압밀침하를 앞당겨 끝내는 공법.', '["시간이 오래 걸리는 것이 약점 — 연직배수공법과 병행해 기간 단축"]'::jsonb, false),
  ('d746e1d8-7d43-5c03-aab5-d4993f067ae2'::uuid, '1장 · 6절 · 연직배수', '샌드드레인 (Sand Drain)', '연약 점토층에 모래 기둥을 촘촘히 박아 간극수의 배수 거리를 수평 방향으로 단축, 압밀을 촉진하는 공법.', '["상부에 샌드매트(수평 배수층) + 프리로딩과 세트로 사용"]'::jsonb, false),
  ('4ba5d415-0542-58a0-9e6e-3c868e90f47f'::uuid, '1장 · 6절 · 연직배수', '페이퍼드레인 (PBD, 플라스틱보드드레인)', '모래 대신 판형 배수재(카드보드)를 박는 연직배수. 시공 빠르고 교란 적으며 경제적 — 현재 주류.', '[]'::jsonb, false),
  ('379ff53d-a602-5751-9ac8-3e0409700186'::uuid, '1장 · 6절 · 연직배수', '팩드레인 (Pack Drain)', '모래를 자루(팩)에 담아 박는 방식. 샌드드레인의 절단(드레인 끊김) 단점을 보완.', '["연직배수 3형제: 샌드(모래 기둥) / 페이퍼(판형 심지) / 팩(자루 속 모래) — 배수 거리를 줄인다는 원리는 동일"]'::jsonb, false),
  ('df47c6e0-f597-510c-b44a-15029da242d2'::uuid, '1장 · 6절 · 다짐·진동', '바이브로플로테이션 (Vibro-flotation)', '봉상 진동기를 물과 함께 관입, 진동+수압으로 느슨한 모래를 다지는 공법.', '["사질토 전용 — 액상화 대책으로도 사용"]'::jsonb, false),
  ('76a06aac-1291-54bb-902b-d2e2613ef00d'::uuid, '1장 · 6절 · 다짐·진동', '동다짐공법 (동압밀)', '수십 톤 추를 크레인으로 높이서 반복 낙하시켜 깊은 지반까지 다지는 공법.', '["넓은 부지에 경제적. 진동·소음이 커 도심 부적합"]'::jsonb, false),
  ('3bfb9560-ed9e-59bc-8785-93370ea9f85b'::uuid, '1장 · 6절 · 다짐·진동', '모래다짐말뚝 (SCP, Sand Compaction Pile)', '케이싱으로 모래를 압입·다짐하며 조밀한 모래 말뚝을 형성 — 지반을 다지면서 복합지반을 만드는 공법.', '["사질토(다짐)·점성토(복합지반) 모두 적용 가능한 범용 공법"]'::jsonb, false),
  ('57890aaa-7045-5542-916c-517d70f4cb96'::uuid, '1장 · 6절 · 주입·고결', '약액주입공법', '지반 간극에 약액(시멘트계·물유리계)을 주입해 고결·차수시키는 공법.', '["목적: 차수(지하수 차단)와 지반 강화. 주입 효과 확인이 어렵다는 것이 약점"]'::jsonb, false),
  ('25e3c135-6dca-5985-b279-8250ca9f8570'::uuid, '1장 · 6절 · 주입·고결', 'LW · JSP · SGR', 'LW는 물유리+시멘트 현탁액 저압 주입(차수 보강의 보편 공법), JSP는 초고압 분사로 지반을 절삭·교반해 원주형 고결체 형성(고압분사 교반), SGR은 이중관으로 급결·완결 약액을 복합 주입하는 차수 공법.', '["''저압으로 스며들게(LW·SGR) vs 고압으로 갈아 만들기(JSP)'' — 주입 압력으로 구분"]'::jsonb, false),
  ('bd018fa0-8b89-5bdb-bfd0-712c862c114b'::uuid, '1장 · 6절 · 주입·고결', '그라우팅', '지반·구조물 틈에 충전재(그라우트)를 주입하는 작업의 총칭. 차수·보강·공극 충전 목적.', '[]'::jsonb, false),
  ('a296b74e-64cd-5b92-9f43-c7d125a6b22b'::uuid, '1장 · 6절 · 주입·고결', '동결공법', '지반에 냉매관을 박아 간극수를 얼려 일시적 차수벽·내력벽을 만드는 공법. 확실하지만 고비용 — 특수 상황용.', '[]'::jsonb, false),
  ('ee7ad4aa-1ad4-5ab8-90ae-4ba3be2861cf'::uuid, '1장 · 6절 · 주입·고결', '전기침투공법', '직류 전기로 간극수를 음극으로 이동시켜 배수하는 공법. 투수성이 매우 낮은 점성토의 특수 배수 대책.', '[]'::jsonb, false),
  ('0a0add73-2518-51e2-843f-17324328ccae'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '기초 · 지정', '기초는 상부 하중을 지반에 전달하는 최하부 구조.', '["''기초(구조체) 밑을 받치는 준비가 지정'' — 기초와 지정을 한 단어처럼 묶어 이해"]'::jsonb, false),
  ('756ace51-0ef8-5fb3-bbca-b698aee2f61f'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '지정', '기초를 받치기 위해 지반을 다지거나 보강한 부분(잡석지정·말뚝지정 등).', '[]'::jsonb, false),
  ('1cb0a16a-596a-54ef-bc69-1c943d2d4a45'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '잡석지정', '기초 밑에 잡석을 세워 깔고 사춤자갈로 틈을 채워 다진 지정. 지반을 다지고 기초 밑면을 정리.', '[]'::jsonb, false),
  ('ceddc421-f7e7-5b3d-9132-0520e2bbf6b6'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '버림콘크리트 (밀창콘크리트)', '잡석지정 위에 얇게 치는 저강도 콘크리트. 먹매김·철근 배근 작업면 확보와 바닥 오염 방지 목적(구조 부재 아님).', '[]'::jsonb, false),
  ('ffca0cc0-f38b-53b9-bbcf-a061f7b9054c'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '독립기초', '기둥 하나를 하나의 기초판이 받치는 형식. 가장 단순, 부등침하에 취약할 수 있어 지중보로 연결.', '[]'::jsonb, false),
  ('1cafd054-60b3-5fe2-8dbe-a9cf06e80432'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '복합기초', '인접한 2개 이상의 기둥을 하나의 기초판이 받치는 형식(대지 경계로 독립기초가 불가할 때 등).', '[]'::jsonb, false),
  ('353b362e-85bc-5994-b7ec-59f26623040f'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '줄기초 (연속기초)', '벽 또는 일련의 기둥을 띠 모양 기초판이 연속으로 받치는 형식. 조적조·벽식 저층에 일반적.', '[]'::jsonb, false),
  ('40d88a31-d6a0-50dc-aa72-b85893b9a806'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '온통기초 (매트기초)', '건물 바닥 전체를 한 장의 두꺼운 기초판으로 받치는 형식.', '["접지압이 낮아지고 부등침하에 유리 — 연약지반·지하실 있는 건물에 보편적", "받는 대상으로 암기: 독립(기둥 1) → 복합(기둥 여러 개) → 줄(벽·열) → 온통(건물 전체)"]'::jsonb, false),
  ('6c891d82-7998-5e04-b964-7c86416aeba6'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '직접기초', '양호한 지반에 기초판으로 직접 지지하는 얕은기초.', '["선택 기준: 지지층 깊이 — 얕으면 직접, 깊으면 말뚝"]'::jsonb, false),
  ('b6ef73de-f1b2-5de4-ac5a-6ef113c8f7ba'::uuid, '1장 · 7절 · 기초구성과 얕은기초', '깊은기초', '말뚝·케이슨으로 깊은 지지층까지 하중을 전달하는 기초.', '[]'::jsonb, false),
  ('eeb28e87-2c01-573c-a43c-6237ff54a782'::uuid, '1장 · 7절 · 말뚝의 종류', '말뚝기초', '말뚝을 통해 상부 하중을 깊은 지지층 또는 주면 마찰로 전달하는 깊은기초.', '[]'::jsonb, false),
  ('d478f772-bf03-5198-905c-ce49111351fc'::uuid, '1장 · 7절 · 말뚝의 종류', '기성말뚝', '공장에서 제작한 말뚝을 현장에서 박거나 매입(PHC·강관 등)하는 방식.', '["기성(품질 균일·시공 빠름·직름 제한) ↔ 현장타설(대구경·저소음·품질관리 어려움)"]'::jsonb, false),
  ('15206864-1dc8-5348-a910-f82d948aace1'::uuid, '1장 · 7절 · 말뚝의 종류', 'PHC말뚝', '프리스트레스를 도입한 고강도 원심성형 콘크리트 말뚝. 국내 기성말뚝의 주력.', '["고강도로 항타 내력 우수, 경제적. 취급 중 균열·두부 파손 주의"]'::jsonb, false),
  ('ec00c664-e256-582a-9ec1-38ff8b0dbc0c'::uuid, '1장 · 7절 · 말뚝의 종류', '강관말뚝', '강관을 말뚝으로 사용. 인성·이음 용접 용이·수평저항 우수, 고가이며 부식 대책(두께 여유 등) 필요.', '[]'::jsonb, false),
  ('f78329b7-73f4-5374-831c-01e2c6b7d480'::uuid, '1장 · 7절 · 말뚝의 종류', '나무말뚝', '소나무 등 생목을 사용한 전통 말뚝. 상시 지하수위 아래에 두어야 부식 방지 — 현재는 소규모·특수 용도.', '[]'::jsonb, false),
  ('2a25360e-6611-5ece-a99b-542ac85d6000'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', '말뚝박기 (타격공법)', '해머 낙하 에너지로 말뚝을 직접 때려 박는 공법. 지지력 확인이 직접적(관입량), 소음·진동이 커 도심 제약.', '[]'::jsonb, false),
  ('71366766-178f-5291-bc5f-ef10db3dc404'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', '디젤해머', '폭발력으로 타격 — 타격력 크지만 소음·매연 심함.', '[]'::jsonb, false),
  ('069a285b-09ba-5a72-890b-7fe4e2517de1'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', '유압해머', '유압 낙하 제어 — 소음 저감, 타격 에너지 조절 가능(현재 주류).', '[]'::jsonb, false),
  ('026d719f-bf1a-51a4-8f48-f3b0e09a3b11'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', '진동공법 (바이브로해머)', '말뚝에 상하 진동을 주어 주면 마찰을 줄이며 관입·인발하는 공법. 시트파일 시공의 표준.', '[]'::jsonb, false),
  ('7d869a77-e445-549c-8ec7-141707a9687c'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', '매입공법', '천공 후 말뚝을 삽입하는 저소음·저진동 공법의 총칭. 도심 말뚝 시공의 주류.', '["타입(때려서 박기: 시끄럽지만 확실) ↔ 매입(뚫고 넣기: 조용하지만 선단 지지 확보 관리 필요)"]'::jsonb, false),
  ('e97583fd-be77-5ce5-9e21-54863c0dd8d3'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', 'SIP 공법', '오거로 천공 → 시멘트풀 주입 → 말뚝 삽입 → (경타)로 마무리하는 대표 매입공법(Soil-cement Injected Precast pile).', '["선단 지지력 확보를 위한 최종 경타와 시멘트풀 품질이 관리 포인트"]'::jsonb, false),
  ('03c70ae2-baff-569a-afd8-c1693e48dad0'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', '프리보링 공법', '말뚝 지름보다 약간 크게 미리 천공한 뒤 말뚝을 세우고 근고액 주입·경타 등으로 정착시키는 매입공법의 총칭.', '[]'::jsonb, false),
  ('4235cd2e-3739-5f6c-a0dd-7410053e84d7'::uuid, '1장 · 7절 · 말뚝시공(타입과매입)', '중굴공법', '중공 말뚝 속에 오거를 넣고 말뚝 선단 아래를 파면서 말뚝을 동시 침설하는 공법. 케이싱 없이 공벽 유지.', '[]'::jsonb, false),
  ('c72bad22-9b18-536c-9cd2-0827531f3fae'::uuid, '1장 · 7절 · 말뚝시공확인시험', '시항타 (시험말뚝)', '본시공 전 대표 위치에 말뚝을 시험 시공하여 관입 깊이·지지력·시공 장비 적정성을 확인하는 절차.', '["시항타 결과로 본항타 관리 기준(최종 관입량 등)을 정함"]'::jsonb, false),
  ('244b9ed6-f135-59b5-8daf-d482a45656f6'::uuid, '1장 · 7절 · 말뚝시공확인시험', '최종관입량 · 리바운드체크', '최종관입량은 마지막 타격 1회(또는 10회 평균)당 말뚝이 들어간 양, 리바운드는 타격 후 되튀는 양.', '["관입량이 작고 리바운드가 크면 선단이 단단한 층에 도달했다는 신호 — 항타 종료 판정 자료"]'::jsonb, false),
  ('b188c4d6-82f6-55f8-9d52-364a39169482'::uuid, '1장 · 7절 · 말뚝시공확인시험', '동재하시험 (PDA)', '항타 시 말뚝 두부에 센서를 붙여 응력파로 지지력을 추정하는 시험. 빠르고 저렴해 널리 사용.', '[]'::jsonb, false),
  ('0166b529-f55e-544b-8608-a5c532cc63d3'::uuid, '1장 · 7절 · 말뚝시공확인시험', '정재하시험', '말뚝에 실제 하중(사하중·반력앵커)을 재하해 하중-침하 관계로 지지력을 직접 확인하는 시험.', '["동재하(응력파로 추정·간편) ↔ 정재하(실하중으로 확인·기준) — 보통 동재하 다수 + 정재하 소수 조합"]'::jsonb, false),
  ('7d9a6df2-727e-5076-ab9a-c8bd7acc5f95'::uuid, '1장 · 7절 · 현장타설말뚝', '현장타설말뚝', '현장에서 대구경으로 천공 → 철근망 삽입 → 콘크리트 타설로 조성하는 말뚝. 고층·대중량 기초의 표준.', '["공벽 유지 방식에 따라 어스드릴 / 베노토(올케이싱) / RCD로 구분"]'::jsonb, false),
  ('a35e7dbf-7b76-5d9d-b090-c12aeb366cbe'::uuid, '1장 · 7절 · 현장타설말뚝', '어스드릴 공법 (Earth Drill)', '회전 버킷으로 굴착하고 안정액으로 공벽을 보호하는 공법. 장비 소형·능률 양호, 점성토에 적합.', '[]'::jsonb, false),
  ('9b7e1465-d860-5f6f-a230-f9e36679739c'::uuid, '1장 · 7절 · 현장타설말뚝', '베노토 공법 (올케이싱)', '케이싱을 요동 압입해 공벽 전체를 강관으로 보호하며 해머그램으로 굴착하는 공법.', '["공벽 붕괴 위험이 없어 확실 — 장비 대형, 케이싱 인발 시 철근 따라 올라옴(공상) 주의"]'::jsonb, false),
  ('d5deacb7-5472-5f4a-8a94-98dd73b95918'::uuid, '1장 · 7절 · 현장타설말뚝', 'RCD 공법 (리버스 서큘레이션 드릴)', '드릴 로드로 굴착하며 굴착토를 물과 함께 로드 내부로 역순환 배출하는 공법. 대심도·수상 시공에 강함.', '["공내 수위를 지하수위보다 2m 이상 높게 유지해 정수압으로 공벽 보호"]'::jsonb, true),
  ('6f06bd52-4e0d-5440-8f20-3244277c00ff'::uuid, '1장 · 7절 · 현장타설말뚝', '케이싱 (Casing)', '천공 시 공벽 붕괴를 막는 강관. 전장 케이싱(베노토)·상부 케이싱(어스드릴 표층 보호) 등.', '[]'::jsonb, false),
  ('9b36b612-976d-532e-9b20-2b8500439faf'::uuid, '1장 · 7절 · 현장타설말뚝', '트레미관 (Tremie Pipe)', '수중·안정액 중 콘크리트를 재료분리 없이 타설하기 위한 수직 관. 관 하단을 콘크리트 속에 묻은 채(2m 이상 관입 유지) 연속 타설.', '[]'::jsonb, true),
  ('3944c6f7-e364-58cd-bd69-db4e5f2033b9'::uuid, '1장 · 7절 · 현장타설말뚝', '슬라임 처리 (Slime)', '굴착 부스러기가 공 바닥에 가라앉은 침전물(슬라임)을 타설 전 제거하는 작업.', '["슬라임을 남기면 말뚝 선단 지지력이 급감 — 현장타설말뚝 품질관리의 최중요 항목"]'::jsonb, false),
  ('2ac32b74-c8fa-57c8-b684-07c654b7750a'::uuid, '1장 · 7절 · 현장타설말뚝', '철근공상 (솟음)', '콘크리트 타설·케이싱 인발 시 철근망이 함께 떠오르는 현상. 콘크리트 유동성·인발 속도 관리로 방지.', '[]'::jsonb, false),
  ('9875ee8a-5d5d-5ff7-b21a-9742eb3d87a5'::uuid, '1장 · 7절 · 말뚝의지지원리', '선단지지말뚝', '말뚝 끝이 단단한 지지층에 닿아 선단저항으로 지지하는 말뚝.', '["실제 말뚝은 둘의 조합 — 지지층이 깊어 닿지 못하면 마찰말뚝으로 설계"]'::jsonb, false),
  ('475fb711-c330-523c-8bf2-9d75657e77a0'::uuid, '1장 · 7절 · 말뚝의지지원리', '마찰말뚝', '말뚝 옆면과 흙의 주면마찰로 지지하는 말뚝.', '[]'::jsonb, false),
  ('861e0a61-919e-56a7-9e23-629ee7e9879f'::uuid, '1장 · 7절 · 말뚝의지지원리', '부마찰력 (Negative Friction)', '말뚝 주변 지반이 말뚝보다 더 침하할 때, 주면마찰이 하중을 지지하는 게 아니라 오히려 말뚝을 아래로 끌어내리는 힘.', '["연약지반 성토·지하수위 저하 후 압밀 진행 구간에서 발생. 대책: 표면처리(SL말뚝), 이중관, 지반개량", "마찰이 ''아군(지지력)''에서 ''적군(하중)''으로 바뀌는 현상 — 방향이 핵심"]'::jsonb, false),
  ('b5e1f79a-3669-5334-8426-5b6b68ed7061'::uuid, '1장 · 7절 · 말뚝의지지원리', '무리말뚝 (군항)', '말뚝 여러 개가 가까이 박혀 지중 응력 범위가 겹치는 상태.', '["겹침 때문에 무리말뚝 지지력 < 낱말뚝 지지력 합계 — 효율 저감(군항 효과)을 고려해 설계"]'::jsonb, false),
  ('5bc5646f-960a-511d-8150-14703c728308'::uuid, '1장 · 7절 · 말뚝의지지원리', '파일캡', '여러 말뚝 두부를 하나로 묶어 기둥 하중을 말뚝들에 분배하는 기초판(확대기초).', '[]'::jsonb, false),
  ('8642cda4-26ba-5b29-a8ba-35c51be55a06'::uuid, '1장 · 7절 · 말뚝의지지원리', '두부정리', '항타·타설 후 말뚝 상단의 손상부·여분(현장타설의 여유 타설분)을 설계 높이로 깨내고 철근을 정리하는 작업.', '["두부 파손·본체 균열이 없도록 절단 — 기초판과의 일체성 확보"]'::jsonb, false)
) as v(id, section, title, definition, points, flagged)
cross join (select id from auth.users limit 1) as u;
